// more readable version below

void mainImage( out vec4 O, vec2 u )
{
    vec2 R = .1* iResolution.xy,
         U = .9* u / R.y * mat2(1,-1,1,1),                  // scaling + 45° rotate
         A = abs( fract(U) -.5 );                           // tiling + inner symmetry

    O = 1. - R.yyyy/3.* abs( max(A.x,A.y) - .3 );           // base diamonds

    for( float i; i++ < 5.; U += vec2(1,2) )                // intertwined tiling
        A = abs( fract(U/5.) -.5 ),                         // larger tile + inner summetry
        abs( max(A.x,A.y) - .1 ) < .04                      // cross not covering diamonds
          ? O = max(O, 1.- R.y* abs(A.x-A.y) ) :O ;
}





